import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_cool_integer(n):
    numbers = list(range(1, n + 1))

    def find_permutation(current_permutation, remaining_numbers, current_sum):
        if not remaining_numbers:
            # Final check: S_n must not be a square. 
            # Note: We checked this outside the recursive function, 
            # but just in case, this is the sum.
            return current_permutation

        for i, x in enumerate(remaining_numbers):
            next_sum = current_sum + x

            if not is_square(next_sum):
                # Try this number
                new_remaining = remaining_numbers[:i] + remaining_numbers[i+1:]

                result = find_permutation(
                    current_permutation + [x], 
                    new_remaining, 
                    next_sum
                )

                if result is not None:
                    return result

        return None

    # Check the necessary condition first: S_n must not be a perfect square
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return False, None

    # Start the search
    result_permutation = find_permutation([], numbers, 0)

    if result_permutation:
        return True, result_permutation
    else:
        return False, None

# Check n = 1 to 15
results = {}
for n in range(1, 16):
    is_cool, permutation = solve_cool_integer(n)
    results[n] = (is_cool, permutation)

