import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def is_cool(n):
    if n == 0:
        return False
    elements = list(range(1, n + 1))

    # Check all permutations
    for p in permutations(elements):
        partial_sums = []
        current_sum = 0
        for x in p:
            current_sum += x
            partial_sums.append(current_sum)

        is_valid = True
        for s in partial_sums:
            if is_perfect_square(s):
                is_valid = False
                break

        if is_valid:
            return True
    return False

# Test small values
